// Signposts and quest markers
function marker(){const group=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(.8,.09,8,22),new THREE.MeshBasicMaterial({color:'#d8ff72'}));ring.rotation.x=Math.PI/2;group.add(ring);const cone=new THREE.Mesh(new THREE.ConeGeometry(.3,.55,8),new THREE.MeshBasicMaterial({color:'#d8ff72'}));cone.position.y=1.5;group.add(cone);scene.add(group);return group}const questMarker=marker();
const story={stage:0,money:180,rep:0,inventory:['Móvil','Llaves'],day:1,built:0,employees:false,open:false,upgrades:0,storyFlags:{}};
const questStages=[
 ['Conoce a Diego','Tu amigo tiene una idea para conseguir tus primeros encargos.','Encuentra a Diego Andre · Universidad'],
 ['Una red de contactos','Diego te presentó a Mara. Acércate a ella y acepta un encargo profesional.','Habla con Mara · Centro'],
 ['Un comienzo prometedor','El trabajo quedó en una invitación y una transición fuera de escena. Busca a Juan Antonio.','Visita a Juan Antonio · Parque'],
 ['Un remedio peculiar','Juan Antonio tiene el remedio. ¡Y Juan Carlos ya piensa en el logo del bar!','Habla con Juan Carlos · Parque'],
 ['Hazte un nombre','Completa trabajos seguros para ahorrar y ganarte la confianza de la ciudad.','Trabajos disponibles por toda la ciudad'],
 ['Un lugar propio','Compra el terreno de La Toño House y reúne materiales.','Terreno en la zona residencial · $500'],
 ['Manos a la obra','El terreno es tuyo. Invierte en materiales y construye el local.','Terreno · Materiales $300'],
 ['La casa se equipa','El edificio está listo. Compra mobiliario y contrata a Tere.','Mobiliario $250 · Contratar personal'],
 ['Gran inauguración','¡Tu sueño abre sus puertas! Junta apoyo para hacerla inolvidable.','Habla con Tere en La Toño House'],
 ['Dueño de la noche','La Toño House está abierta. Administra, mejora y cobra ingresos diarios.','Regresa al bar para administrar']
];
function currentObjective(){const s=questStages[Math.min(story.stage,questStages.length-1)];$('#questTitle').textContent=s[0];$('#questText').textContent=s[1];$('#questTarget').textContent='◆ '+s[2];}
function setMoney(n){story.money=Math.max(0,Math.floor(n));$('#money').textContent='$'+story.money.toLocaleString('es-MX')}
function setRep(n){story.rep=Math.max(story.rep,n);const r=story.rep;$('#rep').textContent='★'.repeat(Math.min(5,Math.floor(r/2)+1))+'☆'.repeat(4-Math.min(4,Math.floor(r/2)));$('#repnum').textContent=r<2?'Novato':r<5?'Conocido':r<9?'Popular':'Leyenda';$('#repbar').style.width=Math.min(100,12+r*10)+'%'}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
function save(){localStorage.setItem('valles-save',JSON.stringify({...story,pos:[player.position.x,player.position.z],rotation:player.rotation.y}));toast('Progreso guardado en este dispositivo ✓')}
function load(){try{const s=JSON.parse(localStorage.getItem('valles-save'));if(s){Object.assign(story,s);setMoney(story.money);setRep(story.rep);if(s.pos)player.position.set(s.pos[0],0,s.pos[1]);player.rotation.y=s.rotation||0;currentObjective();rebuildLot();toast('Partida cargada. ¡Qué bueno verte!')}}catch(e){}}
function makeChoices(options){const cont=$('#choices');cont.innerHTML='';options.forEach(({label,fn,disabled=false})=>{const b=document.createElement('button');b.className='choice';b.textContent=label;b.disabled=disabled;b.onclick=()=>{if(!disabled)fn()};cont.appendChild(b)})}
function openDialog({name,title,text,choices}){$('#speaker').textContent=name;$('#dialogueTitle').textContent=title;$('#dialogueText').textContent=text;makeChoices(choices);$('#dialogueWrap').classList.add('open');dialogOpen=true}
function closeDialog(){if(!dialogOpen)return;$('#dialogueWrap').classList.remove('open');dialogOpen=false}
let dialogOpen=false;window.addEventListener('keydown',e=>{if(e.key==='Escape')closeDialog()});
function advance(stage){if(story.stage<stage){story.stage=stage;currentObjective();saveQuiet();}}
function saveQuiet(){localStorage.setItem('valles-save',JSON.stringify({...story,pos:[player.position.x,player.position.z],rotation:player.rotation.y}))}
function pay(price,label,callback){if(story.money<price){toast('Te faltan $'+(price-story.money)+' para '+label+'. ¡Busca un encargo!');return false}setMoney(story.money-price);callback();saveQuiet();return true}
function npcDialog(d){const genericWork=()=>openDialog({name:d.name,title:'Un encargo amable',text:'¿Puedes ayudarme con una tarea para el evento? Será una jornada de compañía y conversación. Aceptas el contrato y el resto sucede fuera de escena: nada explícito, solo una nota de agradecimiento al terminar.',choices:[{label:'Aceptar el encargo · +$120 y reputación',fn:()=>{closeDialog();setMoney(story.money+120);setRep(story.rep+1);story.day++;toast('Encargo completado fuera de escena · +$120');if(story.stage===4&&story.money>=500){}saveQuiet()}},{label:'Ahora no, gracias',fn:closeDialog}]});
if(d.id==='diego'){openDialog({name:d.name,title:'Todo empieza con una charla',text:'¡Angel Luis! Tengo un contacto en el centro que necesita compañía para una gala. Nada raro: conversación, un contrato claro y después fundido a negro. Tú eliges tus límites, siempre.',choices:[{label:'Me apunto. Voy a conocerla.',fn:()=>{closeDialog();advance(1);setRep(1);toast('Nuevo contacto añadido al mapa: Mara · Centro')}},{label:'Primero quiero tomar un café.',fn:()=>{closeDialog();setMoney(story.money+20);toast('Diego invita el café · +$20')}}]})}
else if(d.id==='client'){openDialog({name:'Mara · Centro',title:'Un contrato sin sorpresas',text:'Busco un acompañante para conversar durante una gala benéfica. Pago justo, límites claros y privacidad. Si aceptas, la escena hace una transición discreta al final de la noche.',choices:[{label:'Aceptar invitación profesional · +$180',fn:()=>{closeDialog();setMoney(story.money+180);setRep(story.rep+1);story.day++;advance(Math.max(story.stage,2));toast('Gala completada · (fuera de escena) +$180')}},{label:'Declinar con amabilidad',fn:()=>{closeDialog();setRep(story.rep+1);toast('Mara agradece tu honestidad · reputación +1')}}]})}
else if(d.id==='juan'){const stage=story.stage;openDialog({name:d.name,title:stage<3?'El remedio de Juan Antonio':'La receta secreta',text:stage<3?'¿Otra vez te sientes raro? Aquí está mi medicina especial de menta y limón. No cura nada real; es parte de nuestra absurda historia. Diego dice que vas camino a algo grande.':'Ya te ves mejor, amigo. Recuerda: el mejor negocio empieza cuidando a la gente.',choices:[{label:stage<3?'Tomar el remedio y seguir adelante':'Compartir una limonada · $15',fn:()=>{closeDialog();if(stage<3){story.inventory.push('Remedio de menta');advance(3);toast('Remedio ficticio añadido al inventario')}else{if(pay(15,'una limonada',()=>{}))toast('¡Salud!')}}},{label:'¿Me ayudas a promocionar el bar?',fn:()=>{closeDialog();setRep(story.rep+1);toast('Juan Antonio difundirá la noticia.')}}]})}
else if(d.id==='carlos'){openDialog({name:d.name,title:'La marca que brilla',text:'LA TOÑO HOUSE necesita una identidad inolvidable: neón lima, buen ambiente y precios honestos. Te regalo el primer diseño. Cuando abras, yo me encargo de la promo.',choices:[{label:'¡Hecho! Diseña el logo.',fn:()=>{closeDialog();story.inventory=[...new Set([...story.inventory,'Diseño de marca'])];setRep(story.rep+1);if(story.stage<4)advance(4);toast('Diseño de marca desbloqueado ✓')}},{label:'¿Cómo consigo dinero?',fn:()=>{closeDialog();toast('Busca los rombos verdes: cada encargo paga $100–$180.')}}]})}
else if(d.id==='prof'){openDialog({name:d.name,title:'Feria universitaria',text:'Necesito una mano con la feria de bienvenida. Recibir gente, repartir programas y conversar con estudiantes. Trabajo digno y pago el mismo día.',choices:[{label:'Ayudar en la feria · +$140',fn:()=>{closeDialog();setMoney(story.money+140);setRep(story.rep+1);story.day++;if(story.stage<4)advance(4);toast('Feria completada · +$140')}},{label:'Ahora no, profesor',fn:closeDialog}]})}
else if(d.id==='vendor'){openDialog({name:d.name,title:'Café con propósito',text:'Prueba el café de la casa. Si llevas cajas al centro, te doy un pago y un pan de canela.',choices:[{label:'Hacer el reparto · +$100',fn:()=>{closeDialog();setMoney(story.money+100);setRep(story.rep+1);if(story.stage<4)advance(4);toast('Reparto completado · +$100')}},{label:'Comprar café · $12',fn:()=>{closeDialog();if(pay(12,'un café',()=>story.inventory.push('Café de Don Chuy')))toast('Café añadido al inventario')}},{label:'En otro momento',fn:closeDialog}]})}
else if(d.id==='builder')builderDialog();else if(d.id==='host')hostDialog();}

