function setRep(n){story.rep=Math.max(story.rep,n);const r=story.rep;$('#rep').textContent='★'.repeat(Math.min(5,Math.floor(r/2)+1))+'☆'.repeat(4-Math.min(4,Math.floor(r/2)));$('#repnum').textContent=r<2?'Novato':r<5?'Conocido':r<9?'Popular':'Leyenda';$('#repbar').style.width=Math.min(100,12+r*10)+'%'}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2500)}
function save(){localStorage.setItem('valles-save',JSON.stringify({...story,pos:[player.position.x,player.position.z],rotation:player.rotation.y}));toast('Progreso guardado en este dispositivo ✓')}
function saveQuiet(){localStorage.setItem('valles-save',JSON.stringify({...story,pos:[player.position.x,player.position.z],rotation:player.rotation.y}))}
function load(){try{const s=JSON.parse(localStorage.getItem('valles-save'));if(s){Object.assign(story,s);setMoney(story.money);setRep(story.rep);if(s.pos)player.position.set(s.pos[0],0,s.pos[1]);player.rotation.y=s.rotation||0;currentObjective();rebuildLot();toast('Partida cargada. ¡Qué bueno verte!')}}catch(e){}}
function makeChoices(options){const cont=$('#choices');cont.innerHTML='';options.forEach(({label,fn,disabled=false})=>{const b=document.createElement('button');b.className='choice';b.textContent=label;b.disabled=disabled;b.onclick=()=>{if(!disabled)fn()};cont.appendChild(b)})}
let dialogOpen=false;function openDialog({name,title,text,choices}){$('#speaker').textContent=name;$('#dialogueTitle').textContent=title;$('#dialogueText').textContent=text;makeChoices(choices);$('#dialogueWrap').classList.add('open');dialogOpen=true}function closeDialog(){if(!dialogOpen)return;$('#dialogueWrap').classList.remove('open');dialogOpen=false}window.addEventListener('keydown',e=>{if(e.key==='Escape')closeDialog()});
function advance(stage){if(story.stage<stage){story.stage=stage;currentObjective();saveQuiet()}}
function pay(price,label,callback){if(story.money<price){toast('Te faltan $'+(price-story.money)+' para '+label+'. ¡Busca un encargo!');return false}setMoney(story.money-price);callback();saveQuiet();return true}
function builderDialog(){const choices=[];if(story.stage>=5&&!story.built){choices.push({label:'Comprar este terreno · $500',fn:()=>pay(500,'el terreno',()=>{story.built=1;advance(6);rebuildLot();closeDialog();toast('¡El terreno es tuyo!')} )})}if(story.stage>=6&&story.built===1){choices.push({label:'Comprar materiales y construir · $300',fn:()=>pay(300,'materiales',()=>{story.built=2;advance(7);rebuildLot();closeDialog();toast('Obra terminada · La Toño House ya tiene techo')} )})}if(story.stage>=7&&story.built===2){choices.push({label:'Mobiliario y equipo · $250',fn:()=>pay(250,'mobiliario',()=>{story.built=3;story.employees=true;advance(8);rebuildLot();closeDialog();toast('Bar equipado · Tere se une al equipo')} )})}choices.push({label:'¿Qué hace falta?',fn:()=>{closeDialog();toast(story.stage<5?'Gana reputación y ahorra $500 para comprar el lote.':story.stage===5?'Compra el lote para empezar la obra.':'Regresa al lote cuando tengas fondos suficientes.')}});choices.push({label:'Luego vuelvo',fn:closeDialog});openDialog({name:'Maestra Lidia · Constructora',title:story.built===0?'Una esquina con futuro':'La obra de tus sueños',text:story.built===0?'Este terreno tiene potencial. Con $500 lo apartamos. Después necesitaremos $300 para construir; el mobiliario y equipo cuestan $250.':'Cada etapa queda guardada. Construimos algo bonito, seguro y accesible para todo el barrio.',choices})}
