function npcDialog(d){const genericWork=()=>openDialog({name:d.name,title:'Un encargo amable',text:'¿Puedes ayudarme con una tarea para el evento? Será una jornada de compañía y conversación. Aceptas el contrato y el resto sucede fuera de escena: nada explícito, solo una nota de agradecimiento al terminar.',choices:[{label:'Aceptar el encargo · +$120 y reputación',fn:()=>{closeDialog();setMoney(story.money+120);setRep(story.rep+1);story.day++;toast('Encargo completado fuera de escena · +$120');if(story.stage===4&&story.money>=500)advance(5);saveQuiet()}},{label:'Ahora no, gracias',fn:closeDialog}]});
if(d.id==='diego'){openDialog({name:d.name,title:'Todo empieza con una charla',text:'¡Angel Luis! Tengo un contacto en el centro que necesita compañía para una gala. Nada raro: conversación, un contrato claro y después fundido a negro. Tú eliges tus límites, siempre.',choices:[{label:'Me apunto. Voy a conocerla.',fn:()=>{closeDialog();advance(1);setRep(1);toast('Nuevo contacto añadido al mapa: Mara · Centro')}},{label:'Primero quiero tomar un café.',fn:()=>{closeDialog();setMoney(story.money+20);toast('Diego invita el café · +$20')}}]})}
else if(d.id==='client'){openDialog({name:'Mara · Centro',title:'Un contrato sin sorpresas',text:'Busco un acompañante para conversar durante una gala benéfica. Pago justo, límites claros y privacidad. Si aceptas, la escena hace una transición discreta al final de la noche.',choices:[{label:'Aceptar invitación profesional · +$180',fn:()=>{closeDialog();setMoney(story.money+180);setRep(story.rep+1);story.day++;advance(Math.max(story.stage,2));toast('Gala completada · (fuera de escena) +$180')}},{label:'Declinar con amabilidad',fn:()=>{closeDialog();setRep(story.rep+1);toast('Mara agradece tu honestidad · reputación +1')}}]})}
else if(d.id==='juan'){const stage=story.stage;openDialog({name:d.name,title:stage<3?'El remedio de Juan Antonio':'La receta secreta',text:stage<3?'¿Otra vez te sientes raro? Aquí está mi medicina especial de menta y limón. No cura nada real; es parte de nuestra absurda historia. Diego dice que vas camino a algo grande.':'Ya te ves mejor, amigo. Recuerda: el mejor negocio empieza cuidando a la gente.',choices:[{label:stage<3?'Tomar el remedio y seguir adelante':'Compartir una limonada · $15',fn:()=>{closeDialog();if(stage<3){story.inventory.push('Remedio de menta');advance(3);toast('Remedio ficticio añadido al inventario')}else if(pay(15,'una limonada',()=>{}))toast('¡Salud!')}},{label:'¿Me ayudas a promocionar el bar?',fn:()=>{closeDialog();setRep(story.rep+1);toast('Juan Antonio difundirá la noticia.')}}]})}
else if(d.id==='carlos'){openDialog({name:d.name,title:'La marca que brilla',text:'LA TOÑO HOUSE necesita una identidad inolvidable: neón lima, buen ambiente y precios honestos. Te regalo el primer diseño. Cuando abras, yo me encargo de la promo.',choices:[{label:'¡Hecho! Diseña el logo.',fn:()=>{closeDialog();story.inventory=[...new Set([...story.inventory,'Diseño de marca'])];setRep(story.rep+1);if(story.stage<4)advance(4);toast('Diseño de marca desbloqueado ✓')}},{label:'¿Cómo consigo dinero?',fn:()=>{closeDialog();toast('Busca los rombos verdes: cada encargo paga $100–$180.')}}]})}
else if(d.id==='prof'){openDialog({name:d.name,title:'Feria universitaria',text:'Necesito una mano con la feria de bienvenida. Recibir gente, repartir programas y conversar con estudiantes. Trabajo digno y pago el mismo día.',choices:[{label:'Ayudar en la feria · +$140',fn:()=>{closeDialog();setMoney(story.money+140);setRep(story.rep+1);story.day++;if(story.stage<4)advance(4);toast('Feria completada · +$140')}},{label:'Ahora no, profesor',fn:closeDialog}]})}
else if(d.id==='vendor'){openDialog({name:d.name,title:'Café con propósito',text:'Prueba el café de la casa. Si llevas cajas al centro, te doy un pago y un pan de canela.',choices:[{label:'Hacer el reparto · +$100',fn:()=>{closeDialog();setMoney(story.money+100);setRep(story.rep+1);if(story.stage<4)advance(4);toast('Reparto completado · +$100')}},{label:'Comprar café · $12',fn:()=>{closeDialog();if(pay(12,'un café',()=>story.inventory.push('Café de Don Chuy')))toast('Café añadido al inventario')}},{label:'En otro momento',fn:closeDialog}]})}
else if(d.id==='builder')builderDialog();else if(d.id==='host')hostDialog();else genericWork()}

